  'report.title': 'Réglages des rapports', 'report.subtitle': 'Diagnostics locaux privés et consentement',
  'report.automatic': 'Rapports de diagnostic automatiques',
  'report.destination': 'Les rapports de diagnostic sont envoyés à https://gamja.top/api/gamja-bot/reports lorsque le service vérifié est disponible. L’envoi est indisponible dans cette version si le destinataire n’a pas été configuré.',
  'report.contents': 'Les rapports contiennent les versions de l’application et de la compilation, le système d’exploitation et l’architecture, l’heure, le composant, l’étape, un code d’erreur fixe, le nombre d’occurrences et jusqu’à 16 transitions fixes. Un échec accompagné d’un diagnostic assaini comprend aussi un ID de corrélation, un motif et une classe d’exception fixes, des trames de pile relatives à l’application, des ID de contexte limités, l’état HTTP et un ID de demande fournisseur validé. Ils ne contiennent ni discussion, ni instructions d’agent, ni texte du fournisseur, ni clés, ni URL, ni chemins d’accueil, ni sortie de processus, ni presse-papiers, ni contenu de navigateur, ni captures d’écran, ni journaux bruts, ni corps de demande ou de réponse. Une description manuelle facultative est séparée et affichée avant l’envoi.',
  'report.retention': 'Les rapports locaux non envoyés expirent après 7 jours. Le destinataire conserve les rapports acceptés pendant 30 jours. Une notice de confidentialité publiée et une procédure d’accès pour les opérateurs sont requises avant d’activer l’envoi en direct.',
  'report.consent': 'Ce choix s’applique à cette installation dans votre profil utilisateur du système d’exploitation pendant cette session de l’application. Il couvre uniquement les nouveaux échecs survenus après son activation. Après le redémarrage de l’application, les rapports automatiques sont désactivés ; réactivez-les pour cette session. La désactivation arrête les nouvelles tentatives automatiques et supprime les rapports automatiques non envoyés. Un rapport déjà reçu ne peut pas être rappelé avec ce bouton.',
  'report.autoSend': 'Envoyer automatiquement les erreurs de diagnostic', 'report.loading': 'Chargement des réglages locaux des rapports…',
  'report.unavailable': 'Envoi indisponible. L’activation automatique sera disponible lorsque le destinataire vérifié sera configuré.',
