  'report.enabled': 'Les rapports automatiques sont activés pour les nouveaux échecs.',
  'report.disabled': 'Les rapports automatiques non envoyés ont été supprimés. Les prochains échecs ne seront pas envoyés automatiquement.',
  'report.enableUnconfirmed': 'Impossible de confirmer l’activation. L’hôte indique que les rapports automatiques sont activés pour cette session.',
  'report.enableFailure': 'Impossible d’activer les rapports automatiques. Ils restent désactivés pour cette session.',
