  'report.disableFailure': 'Impossible de confirmer le refus. L’envoi automatique est peut-être encore activé ; essayez de le désactiver à nouveau.',
  'problem.export': 'Exporter le rapport', 'problem.delete': 'Supprimer le rapport', 'problem.title': 'Signaler un problème',
  'problem.destination': 'Destination : {destination}.',
  'problem.privacy': 'Seuls les champs affichés dans l’aperçu complet du rapport sont envoyés. Les échecs sélectionnés peuvent inclure un ID de corrélation, un motif et une classe d’exception fixes, des trames de pile relatives à l’application, des ID de contexte limités, l’état HTTP et un ID de demande fournisseur validé. Aucune discussion, clé, capture d’écran, journal brut, chemin local, corps de demande ou de réponse, ni aucun fichier n’est recueilli. Le texte que vous saisissez peut contenir des informations personnelles.',
