  "recovery.reviewConfiguration": "Voir les Agents et connexions de cette salle",
  "recovery.configurationHelp": "Cet avis décrit un échec enregistré, pas l’état actuel. Consultez les Agents, connexions et modèles avant toute modification explicite. Ouvrir le panneau ne modifie aucun réglage, ne lance ni authentification, ni test de fonctions, ni nouvelle exécution.",

  "chat.failureReference.title": "Position et code de l’échec",
  "chat.failureReference.copy": "Copier la référence de l’échec",
  "chat.failureReference.manual": "Sélectionner la référence manuellement",
  "chat.failureReference.copied": "Référence de l’échec copiée.",
  "chat.failureReference.help": "Contient uniquement les identifiants salle/événement, codes/références au format validé et une position dans cette app. Aucun texte de conversation, message d’erreur brut ni identifiant secret. Ne partagez que le nécessaire. Le lien ne donne aucun accès et ne prouve pas un échec actuel.",

  "chat.failure.invalidProviderResponse": "La réponse du fournisseur n’a pas pu être traitée lors de cette tentative enregistrée. Vérifiez l’avancement atteint et la connexion/le modèle actuels. Rien n’est relancé automatiquement.",
  "chat.failure.unsupportedOption": "La connexion/le modèle ne prenait pas en charge une option demandée lors de cette tentative enregistrée. Consultez les options et réglages actuels, puis choisissez explicitement toute modification.",
  "chat.failure.secretStoreUnavailable": "L’accès aux identifiants enregistrés était indisponible lors de cette tentative enregistrée. Cela ne prouve pas une clé absente ou invalide. Conservez les valeurs existantes et vérifiez d’abord l’état d’authentification actuel.",
  "recovery.viewFailure": "Voir l’erreur d’origine dans la conversation",
