  "recovery.historyHelp": "Demandes envoyées depuis cette vue pendant cette session. Acceptation ne signifie pas réussite ; une acceptation ultérieure ne résout pas une réponse inconnue antérieure. Ouvrir ne renvoie rien.",
  "results.textFind.memoryHelp": "La recherche et la casse sont mémorisées par salle/résultat/version pendant cette session, pas après redémarrage ou déconnexion. Aucun texte ni position n’est stocké ; pas d’ouverture ou défilement automatique. Les anciens réglages peuvent sortir de la mémoire récente.",
