  "results.fileSave.panelTitle": "Choisir la destination du résultat",
  "results.fileSave.help": "Enregistre uniquement le texte exact reçu de cette version en Markdown UTF-8, sans conversion du rendu, conversation, avis ni autres versions. Un lien est enregistré comme URL sans consulter son contenu. Vous choisissez destination et remplacement.",
  "results.fileSave.limit": "Jusqu’à 2 Mio ; pas de texte vide ni NUL. Changer version/Owner/vue ou fermer ce panneau pendant le choix annule avant écriture. Une écriture commencée ne peut être annulée par navigation. Historique en mémoire de session ; les fichiers restent après déconnexion.",
  "results.fileSave.saved": "Original de cette version enregistré en Markdown.",
  "results.fileSave.size": "Pas de texte vide ni NUL ; limite UTF-8 de 2 Mio. Aucun texte tronqué. Utilisez copier ou sélectionner.",
  "results.fileSave.historyScope": "Tentatives de cette session, salle, résultat et version. Aucun fichier relu ou enregistré. Pas d’historique après déconnexion ou fermeture ; filtrer et replier n’efface rien.",
  "results.comparison.jumpTitle": "Choisir la comparaison par numéro",
