  "results.listKeyboard": "Sur un résultat, ↑/↓ et Début/Fin déplacent le focus dans cette section chargée sans ouvrir le détail. Entrée ou Espace ouvre le résultat. Maintenir Entrée ne le rouvre pas après le retour.",
  "results.filters.openFirstMatch": "Ouvrir la première correspondance",
  "results.filters.openMatchHelp": "Avec une recherche, Entrée ou le bouton ouvre le premier résultat chargé. Confirmer une composition IME ne l’ouvre pas. Pas de recherche dans le texte ou tout le serveur, ni d’enregistrement ou d’exécution.",
  "results.comparison.sourceTools": "Outils du texte original de référence v{version}",
  "recovery.keyedEffect": "Continuer fige le contenu et la clé pour soumettre un message et peut lancer l’Agent et utiliser le fournisseur. Pas de répétition automatique des outils ni de garantie de réussite.",
  "recovery.sameKeyUnknown": "Réponse non confirmée ; la demande d’origine peut être acceptée. Consultez conversation et travail avant de renvoyer explicitement le contenu d’origine avec la même clé.",
