  "recovery.originalKeyBlockedHelp": "Le serveur a refusé ; aucun renvoi avec cette clé. Cela ne prouve pas l’absence de message et ne résout pas les effets antérieurs. Consultez l’état et rédigez explicitement un nouveau message pour un nouveau travail. Aucun changement automatique de clé.",
  "recovery.openReceivedMessage": "Voir le message d’origine trouvé",
  "recovery.receivedMessageHelp": "La conversation reçue contient un message correspondant à la clé, au contenu et à l’Owner d’origine. Cela ne confirme ni la réponse de cette tentative ni la réussite de l’Agent ou outil. Le consulter ne renvoie rien.",
