  "buildInfo.historyThisBuild": "Trouver cette installation · {build}",
  "buildInfo.historyThisBuildHelp": "Recherche les entrées locales installées avec cette étiquette GUI. N’identifie pas le Core/Engine actif et ne prouve aucune vérification. Des entrées absentes ou connexes peuvent donner zéro ou plusieurs résultats ; les filtres restent modifiables.",
  "chat.delivery.requestType": "Type de demande initiale",
