  "chat.delivery.findScope": "Recherche uniquement le texte envoyé des demandes mises de côté dans cette salle et cette session. Les demandes actuelles à traiter restent visibles au-dessus. Le bref aperçu n’est pas le texte complet ; la recherche ne renvoie ni ne résout les demandes.",
