  "connections.modelIdentity.select": "Sélectionner l’ID du modèle",
  "connections.modelIdentity.help": "Copie l’ID exact choisi dans la liste reçue, sans son nom affiché. La sélection et la copie n’enregistrent aucun réglage, n’exécutent pas le modèle et ne vérifient pas ses fonctions.",
  "commandArchive.pageReadHelp": "Les boutons de page placent la lecture au début de la nouvelle page. La recherche, les filtres d’état et les nouveaux enregistrements ne déplacent pas le focus ; changer de page n’exécute aucune action.",
  "commandArchive.failed": "Réponse d’échec reçue",
  "commandArchive.not_sent": "Non envoyé",
  "connections.testSession.historyScope": "Affiche les demandes de cette session pour cette connexion, pas tout l’historique du serveur. La dernière demande, celles en cours et les résultats incertains restent au-dessus ; les anciennes demandes terminées se recherchent par cinq, des plus récentes aux plus anciennes. La consultation ne lance aucun test.",
  "localModels.history.search": "Rechercher les contrôles de fonctions",
  "localModels.history.searchScope": "Recherche seulement le modèle, l’adresse locale, le numéro, l’état et les heures d’observation/test enregistrées dans cet historique reçu. Ne déduit pas les heures de demande absentes et ne recherche pas le corps des rapports. Les rapports ouverts restent tels quels entre pages et filtres ; la consultation ne lance aucun contrôle et ne change aucune fonction disponible.",
  "localModels.previous.title": "Anciennes configurations locales",
  "localModels.previous.scope": "Affiche uniquement les essais de configuration et rapports conservés dans cette session. La configuration précédente la plus récente et les essais en cours ou incertains restent visibles. Le filtre d’état des archives concerne l’enregistrement de la connexion, pas le test de fonctions. Lire un ancien rapport ne restaure pas les saisies, ne crée aucune connexion, ne lance aucun contrôle et ne change aucune fonction disponible.",
  "localModels.previous.noReport": "Aucun rapport de fonctions n’est conservé pour cet essai. Cela ne signifie pas que le modèle ne possède pas ces fonctions.",
  "localModels.reportCopy.title": "Copier ou sélectionner les états des fonctions",
  "localModels.reportCopy.action": "Copier le JSON des états",
  "localModels.reportCopy.manual": "Sélectionner le JSON",
  "localModels.reportCopy.label": "JSON des états reçu",
  "localModels.reportCopy.scope": "Copie uniquement l’ID du modèle reçu, les heures d’observation/test, le nombre de requêtes et les valeurs déclarées/testées/disponibles/motif par fonction. Les valeurs inconnues le restent. Les adresses serveur et champs d’authentification sont exclus. C’est un instantané historique, pas une nouvelle vérification ; copier n’exécute pas de modèle et n’active aucune fonction.",
  "readiness.browse.historyFind": "Rechercher l’historique reçu",
  "readiness.browse.historyFindScope": "Recherche uniquement les 20 enregistrements au maximum reçus pour cette connexion : ID, modèle, résultat, heure, durée et configuration de référence. Affiche cinq éléments par page dans l’ordre reçu. La recherche et les filtres ne chargent pas d’autre historique et ne lancent aucun test ; les éléments hors de la liste reçue ne sont pas recherchés.",
  "readiness.browse.bindingFind": "Rechercher les Agents reçus",
  "readiness.browse.bindingFindScope": "Recherche seulement le nom, l’ID Agent, le modèle et l’état affiché des 50 liens Agent reçus au maximum pour cette connexion, par groupes de 12 dans l’ordre reçu. Configuré ne prouve pas une réponse réussie du modèle ; l’avertissement de limite reste affiché. La recherche et la pagination ne chargent rien, ne modifient aucune affectation et ne lancent aucun test.",
  "readiness.browse.bindingExactHelp": "id:12 correspond à l’ID Agent exact dans cette liste reçue, pas à un ID de connexion ou de salle. Les autres mots recherchent le nom, le modèle et l’état affichés.",
